#include <CGAL/AABB_tree.h>
#include <CGAL/AABB_traits.h>
#include <CGAL/AABB_triangle_primitive.h>

typedef CGAL::Exact_predicates_inexact_constructions_kernel K;
typedef K::Point_3 Point3d;
typedef K::Triangle_3 Triangle3d;

Point3d nearestPoint(const CGAL::AABB_tree<K>& tree, const Point3d& p) {
    // Perform a nearest neighbor search using the AABB tree
    CGAL::Triple<std::pair<K::Point_3, int>, K::FT, int> res = tree.closest_point_and_distance(p);
    if (res.second == 0) {
        return p;
    } else {
        return res.first.first;
    }
}
